// TeamsLite relay.
//
// Microsoft Graph delivers chat change notifications (webhooks) to a public
// HTTPS endpoint. This Worker is that endpoint: it forwards each notification
// to the TeamsLite Mac app over a WebSocket held by a Durable Object.
//
//   POST /notify/<room>   Graph notificationUrl and lifecycleNotificationUrl
//   GET  /ws/<room>       WebSocket kept open by the app ("ping" -> "pong")
//
// <room> is a random 256-bit id generated by the app. Notifications only carry
// resource ids (no message text); the app also verifies Graph's clientState.

import { DurableObject } from "cloudflare:workers";

const ROUTE = /^\/(notify|ws)\/([0-9a-f]{64})$/;
const MAX_BODY = 256 * 1024;

export class Room extends DurableObject {
  constructor(ctx, env) {
    super(ctx, env);
    // Heartbeats are answered by the runtime without waking the object.
    ctx.setWebSocketAutoResponse(new WebSocketRequestResponsePair("ping", "pong"));
  }

  async fetch(request) {
    if (request.headers.get("Upgrade") === "websocket") {
      const [client, server] = Object.values(new WebSocketPair());
      this.ctx.acceptWebSocket(server);
      return new Response(null, { status: 101, webSocket: client });
    }
    const body = await request.text();
    for (const ws of this.ctx.getWebSockets()) {
      try {
        ws.send(body);
      } catch {
        // Socket is closing; the app reconnects and resyncs on its own.
      }
    }
    return new Response(null, { status: 204 });
  }

  webSocketMessage() {}

  webSocketClose(ws, code, reason) {
    try {
      ws.close(code, reason);
    } catch {
      // Already closed (codes such as 1005/1006 cannot be echoed).
    }
  }

  webSocketError() {}
}

export default {
  async fetch(request, env, ctx) {
    const url = new URL(request.url);
    const match = ROUTE.exec(url.pathname);
    if (!match) return new Response("Not found", { status: 404 });

    const [, kind, room] = match;
    const stub = env.ROOMS.get(env.ROOMS.idFromName(room));

    if (kind === "ws") {
      if (request.headers.get("Upgrade") !== "websocket") {
        return new Response("Expected WebSocket", { status: 426 });
      }
      return stub.fetch(request);
    }

    if (request.method !== "POST") return new Response("Method not allowed", { status: 405 });

    // Subscription validation: Graph expects the token echoed back as plain text.
    const token = url.searchParams.get("validationToken");
    if (token !== null) {
      return new Response(token, { status: 200, headers: { "Content-Type": "text/plain" } });
    }

    const body = await request.text();
    if (body.length > MAX_BODY) return new Response("Payload too large", { status: 413 });

    // Answer Graph right away; it expects a 2xx within a few seconds.
    ctx.waitUntil(stub.fetch("https://room/notify", { method: "POST", body }));
    return new Response(null, { status: 202 });
  },
};
